import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for matrix multiplication with register blocking
matmul_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_SIZE 16
#define REG_TILE 4

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    __shared__ float As[TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE];

    int bx = blockIdx.x;
    int by = blockIdx.y;
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Each thread computes REG_TILE x REG_TILE elements
    int row_base = by * TILE_SIZE + ty;
    int col_base = bx * TILE_SIZE + tx;

    // Register arrays for accumulation
    float c_reg[REG_TILE][REG_TILE] = {0};

    for (int m = 0; m < (N + TILE_SIZE - 1) / TILE_SIZE; m++) {
        // Load tiles into shared memory
        if (row_base < N && m * TILE_SIZE + tx < N) {
            As[ty][tx] = A[row_base * N + m * TILE_SIZE + tx];
        } else {
            As[ty][tx] = 0.0f;
        }

        if (col_base < N && m * TILE_SIZE + ty < N) {
            Bs[ty][tx] = B[(m * TILE_SIZE + ty) * N + col_base];
        } else {
            Bs[ty][tx] = 0.0f;
        }

        __syncthreads();

        // Compute using register blocking
        for (int k = 0; k < TILE_SIZE; k++) {
            float a_reg = As[ty][k];
            float b_reg = Bs[k][tx];

            for (int i = 0; i < REG_TILE && (row_base + i * TILE_SIZE/REG_TILE) < N; i++) {
                for (int j = 0; j < REG_TILE && (col_base + j * TILE_SIZE/REG_TILE) < N; j++) {
                    if (i == 0 && j == 0) {
                        c_reg[i][j] += a_reg * b_reg;
                    }
                }
            }
        }

        __syncthreads();
    }

    // Write results back to global memory
    for (int i = 0; i < REG_TILE; i++) {
        for (int j = 0; j < REG_TILE; j++) {
            int row = row_base + i * TILE_SIZE/REG_TILE;
            int col = col_base + j * TILE_SIZE/REG_TILE;
            if (row < N && col < N && i == 0 && j == 0) {
                C[row * N + col] = c_reg[i][j];
            }
        }
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    int N = A.size(0);
    auto C = torch::zeros({N, N}, A.options());

    const int block_size = TILE_SIZE;
    dim3 block(block_size, block_size);
    dim3 grid((N + block_size - 1) / block_size, (N + block_size - 1) / block_size);

    matmul_kernel<<<grid, block>>>(
        A.data_ptr<float>(), 
        B.data_ptr<float>(), 
        C.data_ptr<float>(), 
        N
    );

    return C;
}
"""

